    // ── 与 C 棒契约对齐的调用面（供 .test/check-client-contract.mjs 静态比对）──
    // readPaths: Host 相对前缀的只读路径，必须全部命中 lib/routes.js 的 ROUTES。
    // writeActions: 写操作 action，必须全部命中 lib/write-proxy.js 的 WRITE_ACTIONS。
    var API_PREFIX = 'manage-api'
    var CLIENT_CONTRACT = {
      prefix: '/api/manage-api',
      readPaths: ['/health', '/state', '/monitor', '/usage', '/usage/detail', '/providers/:id/groups'],
      writeActions: [
        'monitor.collect', 'monitor.alerts-read', 'monitor.announcements-read', 'gateway.toggle',
        'provider.balance', 'provider.usage-check', 'provider.sync', 'provider.detect-kind',
        'probes.run', 'fx.refresh', 'decision.order',
      ],
    }

    // ── 平台小工具 ────────────────────────────────────────────────
    function currentDoc() {
      try { return typeof document !== 'undefined' ? document : null } catch (err) { return null }
    }

    function apiUrl(path) {
      var base = ''
      try { base = (currentDoc() && currentDoc().baseURI) || '' } catch (err) { base = '' }
      if (!base) base = 'http://127.0.0.1/'
      // 与朋友版原版一致（recon/.../lib/client.js:159）：DSH 页面 baseURI 为站点根，
      // 相对写法即解析到 /api/manage-api/<path>；不改写成前导斜杠形式。
      return new URL('api/' + API_PREFIX + '/' + path, base).toString()
    }

    /** 统一取数：读成文本再试 JSON；失败折成 {ok:false,...}，绝不抛。 */
    function fetchJson(path, init) {
      var url = apiUrl(path)
      var options = Object.assign({}, init || {})
      var timeoutMs = typeof options.timeoutMs === 'number' ? options.timeoutMs : 20000
      delete options.timeoutMs
      options.headers = Object.assign({ accept: 'application/json' }, options.headers || {})
      options.credentials = 'same-origin'

      var controller = null, timer = null, timedOut = false
      if (typeof AbortController === 'function') {
        controller = new AbortController()
        options.signal = controller.signal
        if (timeoutMs > 0 && typeof setTimeout === 'function') {
          timer = setTimeout(function () { timedOut = true; try { controller.abort() } catch (e) {} }, timeoutMs)
        }
      }
      var clear = function () { if (timer !== null) { clearTimeout(timer); timer = null } }

      return fetch(url, options).then(function (res) {
        return res.text().then(function (text) {
          var body = null
          try { body = text ? JSON.parse(text) : null } catch (e) { body = null }
          if (!res.ok || body === null) {
            var snippet = String(text || '').trim().slice(0, 160)
            return { ok: false, status: res.status, body: body, error: (body && body.error) ? body.error : ('HTTP ' + res.status + '：' + snippet) }
          }
          return { ok: true, status: res.status, body: body }
        })
      }, function (err) {
        var message = err && err.message ? err.message : String(err)
        var aborted = (err && err.name === 'AbortError') || /abort/i.test(message)
        return { ok: false, status: 0, body: null, error: timedOut ? ('请求超时（' + Math.round(timeoutMs / 1000) + 's）') : aborted ? '请求已取消' : ('请求宿主失败：' + message) }
      }).then(function (r) { clear(); return r })
    }

    /** 只读命名查询：命中 CLIENT_CONTRACT.readPaths。 */
    function readState(opts) {
      var q = opts && opts.full ? 'state?full=1' : 'state?light=1'
      return fetchJson(q)
    }
    function readHealth() { return fetchJson('health') }
    function readMonitor(days) { return fetchJson('monitor?days=' + (days || 7)) }
    function readUsage(days) { return fetchJson('usage?days=' + (days || 30)) }
    function readUsageDetail(days) { return fetchJson('usage/detail?days=' + (days || 7) + '&limit=200') }
    function readProviderGroups(id) { return fetchJson('providers/' + encodeURIComponent(id) + '/groups') }

    /** 写操作统一入口：只发 {action, params, payload}，Host 侧按白名单映射 method+path。 */
    function writeOp(action, params, payload) {
      return fetchJson('write', {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ action: action, params: params || {}, payload: payload || {} }),
      }).then(function (res) {
        if (!res.ok) return { ok: false, error: res.error, status: res.status }
        if (res.body && res.body.ok === false) return { ok: false, error: res.body.error || '写操作失败', status: res.status }
        return { ok: true, summary: (res.body && res.body.summary) || {}, body: res.body }
      })
    }

    // ── 数值格式 ─────────────────────────────────────────────────
    function isNum(v) { return typeof v === 'number' && isFinite(v) }
    function fmtMoney(v, d) {
      if (!isNum(v)) return '—'
      var dd = d === undefined ? (Math.abs(v) >= 1 ? 2 : 3) : d
      return '¥' + Number(v).toFixed(dd)
    }
    function fmtCompact(v) {
      if (!isNum(v)) return '—'
      var n = Number(v)
      if (Math.abs(n) >= 1e8) return (n / 1e8).toFixed(2) + '亿'
      if (Math.abs(n) >= 1e4) return (n / 1e4).toFixed(1) + '万'
      return String(Math.round(n))
    }
    function fmtPct(v) {
      if (!isNum(v)) return '—'
      var n = Number(v)
      return (n > 0 ? '+' : '') + n.toFixed(1) + '%'
    }
    function fmtMs(v) {
      if (!v && v !== 0) return '—'
      var n = Number(v)
      if (!isFinite(n) || n <= 0) return '—'
      return n >= 1000 ? (n / 1000).toFixed(1) + 's' : Math.round(n) + 'ms'
    }
    function fmtTime(ts) {
      if (!ts) return '—'
      try { return new Date(ts).toLocaleTimeString(undefined, { hour12: false }) } catch (e) { return '—' }
    }

    function detectLang() {
      try {
        var doc = currentDoc()
        var lang = (doc && doc.documentElement && doc.documentElement.getAttribute('lang')) || ''
        if (!lang && typeof navigator !== 'undefined' && navigator.language) lang = navigator.language
        if (/^zh/i.test(lang)) return 'zh'
        if (/^en/i.test(lang)) return 'en'
      } catch (e) {}
      return 'zh'
    }

    function detectTheme() {
      try {
        var doc = currentDoc()
        var root = doc && doc.documentElement
        var attr = ''
        if (root && root.getAttribute) attr = String(root.getAttribute('data-theme') || root.getAttribute('data-color-scheme') || '').toLowerCase()
        if (attr.indexOf('dark') >= 0) return 'dark'
        if (attr.indexOf('light') >= 0) return 'light'
        var win = typeof window !== 'undefined' ? window : null
        if (win && typeof win.matchMedia === 'function' && win.matchMedia('(prefers-color-scheme: dark)').matches) return 'dark'
      } catch (e) {}
      return 'light'
    }

    function injectStyle(doc, id, css) {
      if (!doc || typeof doc.createElement !== 'function' || !css) return function () {}
      try {
        if (doc.getElementById && doc.getElementById(id)) return function () {}
        var el = doc.createElement('style')
        el.id = id
        el.textContent = css
        ;(doc.head || doc.documentElement).appendChild(el)
        return function () { try { el.remove() } catch (e) {} }
      } catch (e) { return function () {} }
    }

    function injectTheme(doc) {
      var a = injectStyle(doc, THEME_STYLE_ID, THEME_CSS)
      var b = injectStyle(doc, 'dsh-manage-api-extra', EXTRA_CSS)
      return function () { try { a() } catch (e) {} ; try { b() } catch (e) {} }
    }

