    // ── 数据 hook：取 state + health，附带 loading/error ──────────
    function useDaemon(full) {
      var st = useState({ loading: true, state: null, health: null, error: null, at: 0 })
      var data = st[0], set = st[1]
      var load = useCallback(function () {
        set(function (prev) { return Object.assign({}, prev, { loading: true }) })
        var jobs = [readHealth(), readState({ full: !!full })]
        Promise.all(jobs).then(function (res) {
          var health = res[0] && res[0].ok ? res[0].body : null
          var sres = res[1]
          var state = sres && sres.ok ? (sres.body && sres.body.state !== undefined ? sres.body.state : sres.body) : null
          set({
            loading: false,
            health: health,
            state: state,
            error: state ? null : (sres && sres.error ? sres.error : '无法读取 /api/manage-api/state'),
            at: Date.now(),
          })
        })
      }, [full])
      useEffect(function () { load() }, [load])
      return { data: data, reload: load }
    }

